import { LitElement, css, html, nothing, unsafeCSS } from 'lit'
import { customElement, state } from 'lit/decorators.js'
import { keyed } from 'lit/directives/keyed.js'
import { Resources } from '../resources'
import { theme } from './theme'
import { canFullscreen, isFullscreen, readableBoost, toggleFullscreen } from '../device'
import { t } from '../i18n'
import { AudioManager } from '../audio-manager'
import { onSoundUnblocked, soundBlocked, unlockSound } from '../sound-unlock'
import ArtrusiaArt from '../assets/intro/artrusia.jpg'
import ArtrusiaSign from '../assets/intro/artrusia-sign.png'
import BerdolockArt from '../assets/intro/berdolock.jpg'
import AeroliteArt from '../assets/intro/aerolite.jpg'
import GemPath from '../assets/ui/gem.png'

type SlideId = 'artrusia' | 'berdolock' | 'aerolite'

/**
 * The pages of the story, in order (the Voxelhouse art, built by yarn intro; the texts are in
 * t().intro.slides). `artFirst`: the art on the left and the text on the right. `sign`: an image
 * in place of the written title (the Artrúsia sign; the title is then its alt text).
 */
const SLIDES: { id: SlideId, art: string, artFirst: boolean, sign?: string }[] = [
  { id: 'artrusia', art: ArtrusiaArt, artFirst: false, sign: ArtrusiaSign },
  { id: 'berdolock', art: BerdolockArt, artFirst: true },
  { id: 'aerolite', art: AeroliteArt, artFirst: false }
]

/** The title shows first, then each paragraph this long after the previous one (ms) */
const PARAGRAPH_DELAY = 700
/** Fade to black at the end, music fade included (ms) */
const LEAVE_TIME = 700
const TEXT_SCALE = 1.3
const MAX_TEXT_BOOST = 1.4

/**
 * Opening story, right after the loading screen and before the title: three pages with the
 * Voxelhouse art and text, and their own music. Next (Enter, Space, →) and Back (←) go through the
 * pages; Skip (Esc) or Play on the last page end it with a `done` event (main.ts then mounts the
 * title screen). Nothing advances on its own.
 */
@customElement('intro-story')
export class IntroStory extends LitElement {
  static styles = [theme, css`
    :host { position: fixed; inset: 0; z-index: 1000; display: block; overflow: hidden; background: #000; }
    .slide {
      position: absolute; inset: 0; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
      /* one row exactly as tall as the room left: the art fits in it instead of growing past the screen */
      grid-template-rows: minmax(0, 1fr); align-items: stretch;
      gap: calc(70 * var(--u)); padding: calc(110 * var(--u)) calc(100 * var(--u)) calc(130 * var(--u));
      box-sizing: border-box; animation: slide-in 700ms steps(7) both;
    }
    @keyframes slide-in { from { opacity: 0; } }
    .slide.artrusia { background: radial-gradient(ellipse at 75% 50%, rgba(40, 90, 200, 0.22), transparent 60%), #000; }
    .slide.berdolock { background: radial-gradient(ellipse at 25% 50%, rgba(130, 40, 70, 0.25), transparent 60%), #000; }
    .slide.aerolite { background: radial-gradient(ellipse at 75% 50%, rgba(220, 130, 40, 0.18), transparent 60%), #000; }

    /* the picture fills its cell and keeps its proportions (contain): never cut, on any screen */
    .art { position: relative; min-height: 0; min-width: 0; }
    .art img {
      position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; image-rendering: auto;
      filter: drop-shadow(0 0 calc(30 * var(--u)) rgba(0, 0, 0, 0.9));
      animation: art-in 1200ms ease-out both, drift 40s linear 1200ms both;
    }
    @keyframes art-in { from { opacity: 0; transform: scale(0.96); } }
    /* a slow push-in, the "camera" of the scene */
    @keyframes drift { to { transform: scale(1.05); } }
    .artFirst .art { order: -1; }

    .text { align-self: center; max-height: 100%; overflow-y: auto; padding-right: calc(16 * var(--u)); display: flex; flex-direction: column; gap: calc(22 * var(--u)); scrollbar-color: var(--edge) transparent; scrollbar-width: thin; }
    .text > * { animation: line-in 600ms steps(6) both; }
    /* opacity only: a line sliding in from below would stick out of the column and show its scrollbar for a moment */
    @keyframes line-in { from { opacity: 0; } }
    .revealed .text > * { animation: none; }
    h1 {
      margin: 0; font-weight: normal; font-size: calc(40 * var(--t)); line-height: 1.15; text-transform: uppercase; align-self: flex-start;
    }
    /* lighten: the black around the sign (a JPEG crop) disappears into the background */
    .sign { width: calc(440 * var(--u)); max-width: 100%; height: auto; align-self: center; image-rendering: auto; mix-blend-mode: lighten; }
    p { margin: 0; font-size: calc(19 * var(--t)); line-height: 1.5; text-shadow: calc(2 * var(--u)) calc(2 * var(--u)) 0 #000; }

    .controls {
      position: absolute; left: calc(100 * var(--u)); right: calc(100 * var(--u)); bottom: calc(40 * var(--u));
      display: flex; align-items: center; gap: calc(16 * var(--u));
    }
    .dots { display: flex; gap: calc(12 * var(--u)); flex: 1; }
    /* the pages are gems: lit on the current one */
    .dot { width: calc(9 * var(--px)); height: calc(11 * var(--px)); background: url(${unsafeCSS(GemPath)}) center / 100% 100% no-repeat; filter: grayscale(1) brightness(0.45); }
    .dot.on { filter: drop-shadow(0 0 calc(2 * var(--px)) rgba(240, 74, 74, 0.6)); }
    .btn { font-size: calc(26 * var(--t)); padding: calc(7 * var(--u)) calc(24 * var(--u)); white-space: nowrap; }
    .top { position: absolute; top: calc(30 * var(--u)); right: calc(36 * var(--u)); display: flex; gap: calc(14 * var(--u)); }
    .top .btn { font-size: calc(20 * var(--t)); padding: calc(5 * var(--u)) calc(18 * var(--u)); }
    .sound-hint {
      position: absolute; top: calc(30 * var(--u)); left: calc(36 * var(--u)); font-size: calc(20 * var(--t));
      padding: calc(8 * var(--u)) calc(20 * var(--u)); animation: blink 1.6s steps(2) infinite;
    }
    @keyframes blink { 50% { opacity: 0.6; } }

    .fade { position: absolute; inset: 0; background: #000; opacity: 0; pointer-events: none; transition: opacity ${LEAVE_TIME}ms steps(7); }
    .fade.visible { opacity: 1; pointer-events: auto; }
  `]

  @state()
  private index = 0

  /** Every line of the page already in view (a Next while they still come in shows them all first) */
  @state()
  private revealed = false

  @state()
  private leaving = false

  @state()
  private soundOff = soundBlocked()

  private revealTimer: number | undefined
  private stopSound: (() => void) | null = null

  private onKeyDown = (event: KeyboardEvent) => {
    // Enter on a focused button is already its click
    if (event.composedPath()[0] instanceof HTMLButtonElement && (event.key === 'Enter' || event.key === ' ')) return
    if (event.key === 'Escape') this.finish()
    else if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowRight') this.next()
    else if (event.key === 'ArrowLeft') this.previous()
    else return
    event.preventDefault()
  }

  private onResize = () => this.updateScale()

  @state()
  private fullscreen = isFullscreen()

  private onFullscreenChange = () => { this.fullscreen = isFullscreen() }

  override connectedCallback() {
    super.connectedCallback()
    this.updateScale()
    window.addEventListener('resize', this.onResize)
    window.addEventListener('keydown', this.onKeyDown)
    document.addEventListener('fullscreenchange', this.onFullscreenChange)
    document.addEventListener('webkitfullscreenchange', this.onFullscreenChange)
    Resources.IntroMusic.loop = true
    // started even while the browser keeps the page silent: heard from the first click on
    Resources.IntroMusic.play()
    this.stopSound = onSoundUnblocked(() => { this.soundOff = false })
    this.startReveal()
  }

  override disconnectedCallback() {
    window.removeEventListener('resize', this.onResize)
    window.removeEventListener('keydown', this.onKeyDown)
    document.removeEventListener('fullscreenchange', this.onFullscreenChange)
    document.removeEventListener('webkitfullscreenchange', this.onFullscreenChange)
    window.clearTimeout(this.revealTimer)
    this.stopSound?.()
    Resources.IntroMusic.stop()
    super.disconnectedCallback()
  }

  /** The same scale as the start screen: 1 --u = 1 px at 1920x1080, text a bit larger on phones */
  private updateScale() {
    const scale = Math.min(window.innerWidth / 1920, window.innerHeight / 1080)
    const boost = Math.min(MAX_TEXT_BOOST, readableBoost(scale * TEXT_SCALE))
    this.style.setProperty('--s', scale.toFixed(4))
    this.style.setProperty('--text-scale', (TEXT_SCALE * boost).toFixed(4))
  }

  private startReveal() {
    this.revealed = false
    window.clearTimeout(this.revealTimer)
    const lines = t().intro.slides[SLIDES[this.index].id].paragraphs.length
    this.revealTimer = window.setTimeout(() => { this.revealed = true }, (lines + 1) * PARAGRAPH_DELAY)
  }

  private show(index: number) {
    Resources.SelectSound.play()
    this.index = index
    this.startReveal()
  }

  private next() {
    if (this.leaving) return
    if (!this.revealed) {
      window.clearTimeout(this.revealTimer)
      this.revealed = true
    } else if (this.index < SLIDES.length - 1) {
      this.show(this.index + 1)
    } else {
      this.finish()
    }
  }

  private previous() {
    if (this.leaving || this.index === 0) return
    this.show(this.index - 1)
  }

  /** Fades the picture and the music out, then hands over to the title screen */
  private finish() {
    if (this.leaving) return
    this.leaving = true
    Resources.SelectSound.play()
    const music = Resources.IntroMusic
    const start = music.volume
    const steps = 10
    for (let i = 1; i <= steps; i++) {
      window.setTimeout(() => { music.volume = start * (1 - i / steps) }, i * LEAVE_TIME / steps)
    }
    window.setTimeout(() => {
      music.stop()
      AudioManager.init() // its volume back, for the next time it plays
      this.dispatchEvent(new CustomEvent('done'))
    }, LEAVE_TIME + 50)
  }

  private renderSlide() {
    const slide = SLIDES[this.index]
    const text = t().intro.slides[slide.id]
    const delay = (line: number) => `animation-delay: ${line * PARAGRAPH_DELAY}ms`
    const title = slide.sign
      ? html`<img class="sign" src=${slide.sign} alt=${text.title} style=${delay(0)} />`
      : html`<h1 class="gold-text" style=${delay(0)}>${text.title}</h1>`
    return keyed(slide.id, html`
      <section class="slide ${slide.id} ${slide.artFirst ? 'artFirst' : ''} ${this.revealed ? 'revealed' : ''}">
        <div class="text">
          ${title}
          ${text.paragraphs.map((paragraph, i) => html`<p style=${delay(i + 1)}>${paragraph}</p>`)}
        </div>
        <div class="art"><img src=${slide.art} alt="" /></div>
      </section>
    `)
  }

  override render() {
    const text = t().intro
    const last = this.index === SLIDES.length - 1
    return html`
      ${this.renderSlide()}
      ${this.soundOff && !AudioManager.muted ? html`<button class="btn btn-solid sound-hint" @click=${() => unlockSound()}>♪ ${t().title.playMusic}</button>` : nothing}
      <div class="top">
        ${canFullscreen() ? html`<button class="btn btn-solid ${this.fullscreen ? 'on' : ''}" @click=${() => toggleFullscreen()}>${t().audio.fullscreen}</button>` : nothing}
        <button class="btn btn-solid skip" @click=${() => this.finish()}>${text.skip} ▶▶</button>
      </div>
      <div class="controls">
        <div class="dots">${SLIDES.map((_, i) => html`<span class="dot ${i === this.index ? 'on' : ''}"></span>`)}</div>
        ${this.index > 0 ? html`<button class="btn btn-solid" @click=${() => this.previous()}>${text.previous}</button>` : nothing}
        <button class="btn btn-solid primary" @click=${() => this.next()}>${last && this.revealed ? text.start : text.next}</button>
      </div>
      <div class="fade ${this.leaving ? 'visible' : ''}"></div>
    `
  }
}
