/**
 * Movement of ONAGRO (guide, "Movimentação"): hexes counted one by one,
 * terrain by type, and the Zone of Control. Pure: it only needs the map and
 * a way to ask who stands on a hex.
 *
 * - easy terrain costs 1 per hex, hard terrain 2 (half the MO, rounded down)
 * - very hard terrain (river, lake): the unit moves only 1 hex, and it also
 *   moves only 1 hex when it starts the move inside one
 * - blocked terrain (wall, rock, mountain) cannot be entered
 * - allies can be crossed but not stopped on; enemies cannot be crossed
 * - a hex next to an enemy is in its ZOC: entering it engages, but the unit may
 *   walk on. Every hex in an enemy ZOC the unit leaves (the start hex too:
 *   disengaging) costs an opportunity attack, a rule of the turn (`Game.move`).
 *   Of the paths that fit the MO, the map takes the one with the lightest
 *   attacks (an attack weighs 1 + the enemies around that hex), then the cheapest.
 */
import { Axial, hexKey, hexNeighbors } from '../hex'
import { MapData, Terrain, inMap, terrainAt } from './terrain'
import { Player, UnitState, inPlay } from './units'

export interface MoveContext {
  map: MapData
  /** The unit standing on the hex, if any */
  unitAt(hex: Axial): UnitState | null
}

/** Movement spent to enter a hex of this terrain; Infinity when it cannot be entered */
export function entryCost(terrain: Terrain, budget: number): number {
  switch (terrain.move) {
  case 'easy': return 1
  case 'hard': return 2
  case 'veryHard': return budget
  case 'blocked': return Infinity
  }
}

/** Movement points a unit starts a move with: its MO, or 1 inside very hard terrain */
export function startBudget(ctx: MoveContext, unit: UnitState): number {
  const here = unit.pos ? terrainAt(ctx.map, unit.pos) : null
  return here?.move === 'veryHard' ? Math.min(1, unit.sheet.stats.mo) : unit.sheet.stats.mo
}

/** Enemy units (in play) next to a hex */
export function enemiesAround(ctx: MoveContext, hex: Axial, owner: Player): UnitState[] {
  const result: UnitState[] = []
  for (const n of hexNeighbors(hex)) {
    const unit = ctx.unitAt(n)
    if (unit && inPlay(unit) && unit.owner !== owner) result.push(unit)
  }
  return result
}

/** Is the hex inside the Zone of Control of an enemy of `owner`? */
export const isInEnemyZoc = (ctx: MoveContext, hex: Axial, owner: Player): boolean => enemiesAround(ctx, hex, owner).length > 0

export interface MovementMap {
  start: Axial
  /** Hexes the unit can stop on (the start hex is not included) */
  range: Axial[]
  canStopAt(hex: Axial): boolean
  costTo(hex: Axial): number
  /** Hexes from the start to `hex`, both included; empty when it cannot be reached */
  pathTo(hex: Axial): Axial[]
  /** The hexes of the path to `hex` the unit leaves inside an enemy ZOC, in order: one opportunity attack each */
  attacksOn(hex: Axial): Axial[]
}

interface Label {
  hex: Axial
  spent: number
  /** Weight of the opportunity attacks on the way here */
  risk: number
  previous: string | null
}

/** Everything `unit` can reach with one move, each hex by its safest path */
export function movementMap(ctx: MoveContext, unit: UnitState): MovementMap {
  if (!unit.pos) throw new Error('The unit is not on the map')
  const start = unit.pos
  const startKey = hexKey(start)
  const budget = startBudget(ctx, unit)

  const weights = new Map<string, number>()
  /** What leaving the hex weighs: nothing outside an enemy ZOC, else 1 + the enemies around */
  const leaving = (hex: Axial): number => {
    const key = hexKey(hex)
    let weight = weights.get(key)
    if (weight === undefined) {
      const enemies = enemiesAround(ctx, hex, unit.owner).length
      weight = enemies > 0 ? 1 + enemies : 0
      weights.set(key, weight)
    }
    return weight
  }

  // labels by (hex, movement spent): every step costs 1 or more, so the levels go up one by one
  const labels = new Map<string, Label>()
  const levels: string[][] = Array.from({ length: budget + 1 }, () => [])
  const first = `${startKey}|0`
  labels.set(first, { hex: start, spent: 0, risk: 0, previous: null })
  levels[0].push(first)
  for (let spent = 0; spent <= budget; spent++) {
    for (const key of levels[spent]) {
      const label = labels.get(key)!
      const risk = label.risk + leaving(label.hex)
      for (const next of hexNeighbors(label.hex)) {
        if (!inMap(ctx.map, next)) continue
        const terrain = terrainAt(ctx.map, next)
        if (!terrain) continue
        const occupant = ctx.unitAt(next)
        if (occupant && inPlay(occupant) && occupant.owner !== unit.owner) continue
        const total = spent + entryCost(terrain, budget)
        if (total > budget) continue
        const nextKey = `${hexKey(next)}|${total}`
        const known = labels.get(nextKey)
        if (known && known.risk <= risk) continue
        labels.set(nextKey, { hex: next, spent: total, risk, previous: key })
        if (!known) levels[total].push(nextKey)
      }
    }
  }

  // the best way to each hex: the lightest attacks, then the least movement
  const best = new Map<string, { label: Label, key: string }>()
  for (const [key, label] of labels) {
    const hex = hexKey(label.hex)
    const known = best.get(hex)
    if (!known || label.risk < known.label.risk || (label.risk === known.label.risk && label.spent < known.label.spent)) best.set(hex, { label, key })
  }

  const range: Axial[] = []
  const stoppable = new Set<string>()
  for (const [key, { label }] of best) {
    if (key === startKey) continue
    const occupant = ctx.unitAt(label.hex)
    if (occupant && inPlay(occupant)) continue
    range.push(label.hex)
    stoppable.add(key)
  }

  const pathTo = (hex: Axial): Axial[] => {
    const found = stoppable.has(hexKey(hex)) ? best.get(hexKey(hex)) : undefined
    if (!found) return []
    const path: Axial[] = []
    for (let key: string | null = found.key; key !== null; key = labels.get(key)!.previous) path.unshift(labels.get(key)!.hex)
    return path
  }

  return {
    start,
    range,
    canStopAt: hex => stoppable.has(hexKey(hex)),
    costTo: hex => (stoppable.has(hexKey(hex)) ? best.get(hexKey(hex))!.label.spent : Infinity),
    pathTo,
    attacksOn: hex => pathTo(hex).slice(0, -1).filter(step => leaving(step) > 0)
  }
}
