/**
 * Pure combat rules of ONAGRO (guide, "Como causar dano" and "Ataques a
 * distância"). No engine, no game state: pools of d6 in, damage out.
 *
 * The attacker rolls PA dice and the defender rolls PD dice. Both are sorted
 * from the highest to the lowest and compared in pairs:
 * - defense >= attack: blocked (a tie favors the defender)
 * - attack > defense: 1 damage to the defender
 * - attack dice with no defense die to face: 1 damage each, except results of 1
 * - defense dice with no attack die to face: ignored
 * - melee only: an attack die of 1 compared to a defense of 2+ hurts the attacker
 *
 * Order of everything that changes the dice (one rule so the real roll and the
 * forecast always agree): roll the attack pool, Block (the highest die is
 * rolled again), Fury (one die may be rolled again), Shaken (-1 per die), then
 * roll the defense pool, add the defense bonus to its highest die ("PD 1d6+2") and
 * compare.
 */
import { Dice, rollPool, sortedDesc } from './dice'
import type { Cover } from './terrain'

export interface AttackMods {
  /** The target has Block: the attacker rolls its highest die again */
  rerollHighest: boolean
  /** The attacker has Fury: it rolls one die again (its lowest, when that is not good enough) */
  fury: boolean
  /** The attacker is Shaken (melee only): -1 on each die, 1s stay 1s */
  shaken: boolean
}

export const NO_MODS: AttackMods = { rerollHighest: false, fury: false, shaken: false }

/** Fury rerolls the lowest die when it shows this or less (below the 3.5 average of a fresh die) */
export const FURY_REROLL_UP_TO = 3

export interface StrikeSetup {
  /** d6 of PA (bonuses already added) */
  attackDice: number
  /** d6 of PD (bonuses already added) */
  defenseDice: number
  /** Added to the highest defense die ("PD 1d6+2": 1 die, bonus 2) */
  defenseBonus?: number
  /** Melee: a 1 against a defense of 2+ hurts the attacker */
  melee: boolean
  mods: AttackMods
}

export type PairEffect = 'blocked' | 'hit' | 'excess' | 'ignored' | 'backlash'

export interface Pair {
  attack: number
  /** The defense die it was compared with; null when there was none */
  defense: number | null
  effect: PairEffect
}

export interface Comparison {
  defenderDamage: number
  attackerDamage: number
  pairs: Pair[]
}

/** Compares an attack pool with a defense pool (any order: both get sorted) */
export function compareDice(attack: number[], defense: number[], melee: boolean): Comparison {
  const a = sortedDesc(attack)
  const d = sortedDesc(defense)
  const pairs: Pair[] = []
  let defenderDamage = 0
  let attackerDamage = 0
  a.forEach((die, i) => {
    if (i < d.length) {
      const against = d[i]
      if (die > against) {
        defenderDamage++
        pairs.push({ attack: die, defense: against, effect: 'hit' })
      } else if (melee && die === 1 && against >= 2) {
        attackerDamage++
        pairs.push({ attack: die, defense: against, effect: 'backlash' })
      } else {
        pairs.push({ attack: die, defense: against, effect: 'blocked' })
      }
    } else if (die === 1) {
      pairs.push({ attack: die, defense: null, effect: 'ignored' })
    } else {
      defenderDamage++
      pairs.push({ attack: die, defense: null, effect: 'excess' })
    }
  })
  return { defenderDamage, attackerDamage, pairs }
}

export interface StrikeRoll {
  /** The attack dice as first rolled */
  attackRolled: number[]
  /** The attack dice after Block, Fury and Shaken, highest first */
  attackFinal: number[]
  /** The defense dice, highest first (the bonus already added to the highest) */
  defense: number[]
  comparison: Comparison
}

const shakenDie = (die: number) => (die > 1 ? die - 1 : 1)

/** Adds the defense bonus to the highest die of a sorted pool (it stays the highest) */
const withBonus = (sorted: number[], bonus: number): number[] =>
  bonus === 0 || sorted.length === 0 ? sorted : [sorted[0] + bonus, ...sorted.slice(1)]

/** Rolls a whole attack: attack pool, Block, Fury, Shaken, defense pool, comparison */
export function rollStrike(dice: Dice, setup: StrikeSetup): StrikeRoll {
  const attackRolled = rollPool(dice, setup.attackDice)
  const pool = [...attackRolled]
  if (setup.mods.rerollHighest && pool.length > 0) pool[pool.indexOf(Math.max(...pool))] = dice.d6()
  if (setup.mods.fury && pool.length > 0) {
    const lowest = pool.indexOf(Math.min(...pool))
    if (pool[lowest] <= FURY_REROLL_UP_TO) pool[lowest] = dice.d6()
  }
  const attackFinal = sortedDesc(setup.mods.shaken ? pool.map(shakenDie) : pool)
  const defense = withBonus(sortedDesc(rollPool(dice, setup.defenseDice)), setup.defenseBonus ?? 0)
  return { attackRolled, attackFinal, defense, comparison: compareDice(attackFinal, defense, setup.melee) }
}

// ---------------------------------------------------------------- forecast

/** One possible pool (sorted, highest first) and how likely it is */
interface Outcome {
  dice: number[]
  p: number
}

const factorial = (n: number): number => (n <= 1 ? 1 : n * factorial(n - 1))
const outcomeCache = new Map<number, Outcome[]>()

/** Every distinct pool of `n` dice with its exact probability (multisets, not 6^n rolls) */
function poolOutcomes(n: number): Outcome[] {
  const cached = outcomeCache.get(n)
  if (cached) return cached
  const result: Outcome[] = []
  const counts = [0, 0, 0, 0, 0, 0]
  const walk = (face: number, left: number) => {
    if (face === 0) {
      if (left !== 0) return
      const dice: number[] = []
      let ways = factorial(n)
      for (let f = 6; f >= 1; f--) {
        for (let k = 0; k < counts[f - 1]; k++) dice.push(f)
        ways /= factorial(counts[f - 1])
      }
      result.push({ dice, p: ways / 6 ** n })
      return
    }
    for (let c = 0; c <= left; c++) {
      counts[face - 1] = c
      walk(face - 1, left - c)
    }
    counts[face - 1] = 0
  }
  walk(6, n)
  outcomeCache.set(n, result)
  return result
}

/** Applies a rule to every outcome (`rule` may split an outcome in several) and merges equal pools */
function transform(outcomes: Outcome[], rule: (dice: number[]) => Outcome[]): Outcome[] {
  const merged = new Map<string, Outcome>()
  for (const outcome of outcomes) {
    for (const next of rule(outcome.dice)) {
      const key = next.dice.join('')
      const known = merged.get(key)
      const p = next.p * outcome.p
      if (known) known.p += p
      else merged.set(key, { dice: next.dice, p })
    }
  }
  return [...merged.values()]
}

const rerollAt = (dice: number[], index: number): Outcome[] =>
  [1, 2, 3, 4, 5, 6].map(face => {
    const next = [...dice]
    next[index] = face
    return { dice: sortedDesc(next), p: 1 / 6 }
  })

export interface StrikeForecast {
  /** defenderDamage[i] = chance the defender loses exactly i PV */
  defenderDamage: number[]
  /** attackerDamage[i] = chance the attacker loses exactly i PV (melee backlash) */
  attackerDamage: number[]
  expectedDefenderDamage: number
  expectedAttackerDamage: number
}

/** Chance that a damage distribution gives at least `amount` */
export function chanceAtLeast(distribution: number[], amount: number): number {
  let total = 0
  distribution.forEach((p, damage) => { if (damage >= amount) total += p })
  return Math.min(1, total)
}

const forecastCache = new Map<string, StrikeForecast>()

/**
 * Exact odds of an attack, by enumerating every pool. Same rules as `rollStrike`.
 * Cached by dice and modifiers (the AI asks for the same few setups thousands of
 * times); the result is shared, do not change it.
 */
export function forecastStrike(setup: StrikeSetup): StrikeForecast {
  const { mods } = setup
  const key = `${setup.attackDice}|${setup.defenseDice}+${setup.defenseBonus ?? 0}|${setup.melee ? 1 : 0}${mods.rerollHighest ? 1 : 0}${mods.fury ? 1 : 0}${mods.shaken ? 1 : 0}`
  let result = forecastCache.get(key)
  if (!result) {
    result = computeForecast(setup)
    forecastCache.set(key, result)
  }
  return result
}

function computeForecast(setup: StrikeSetup): StrikeForecast {
  let attacks = poolOutcomes(setup.attackDice)
  if (setup.mods.rerollHighest && setup.attackDice > 0) attacks = transform(attacks, dice => rerollAt(dice, 0))
  if (setup.mods.fury && setup.attackDice > 0) {
    attacks = transform(attacks, dice => {
      const last = dice.length - 1
      return dice[last] <= FURY_REROLL_UP_TO ? rerollAt(dice, last) : [{ dice, p: 1 }]
    })
  }
  if (setup.mods.shaken) attacks = transform(attacks, dice => [{ dice: dice.map(shakenDie), p: 1 }])
  const bonus = setup.defenseBonus ?? 0
  const defenses = poolOutcomes(setup.defenseDice).map(outcome => ({ dice: withBonus(outcome.dice, bonus), p: outcome.p }))

  const defenderDamage = new Array<number>(setup.attackDice + 1).fill(0)
  const attackerDamage = new Array<number>(setup.attackDice + 1).fill(0)
  for (const attack of attacks) {
    for (const defense of defenses) {
      const result = compareDice(attack.dice, defense.dice, setup.melee)
      const p = attack.p * defense.p
      defenderDamage[result.defenderDamage] += p
      attackerDamage[result.attackerDamage] += p
    }
  }
  const mean = (dist: number[]) => dist.reduce((sum, p, damage) => sum + p * damage, 0)
  return {
    defenderDamage,
    attackerDamage,
    expectedDefenderDamage: mean(defenderDamage),
    expectedAttackerDamage: mean(attackerDamage)
  }
}

// ------------------------------------------------------------------ ranged

/** Cover adds to the RA the shooter needs (guide, "Cobertura") */
export const COVER_MODIFIER: Record<Cover, number> = { none: 0, light: 1, heavy: 2 }

/**
 * Friendly fire: shooting at an enemy engaged with an ally, the hit roll decides it all. Enough for the
 * RA hits the enemy, less misses, and this result hits an ally engaged with it (Voxelhouse, 26/11/2026)
 */
export const FRIENDLY_FIRE_ROLL = 1

/**
 * The d6 result needed to hit: weapon RA - the shooter's hit bonus + the
 * target's cover. A 1 always misses and a 6 always hits (the guide does not
 * say, this keeps every shot possible but never certain).
 */
export function targetNumber(ra: number, hitBonus: number, cover: Cover): number {
  return Math.min(6, Math.max(2, ra - hitBonus + COVER_MODIFIER[cover]))
}

/** Chance of rolling `target` or more on 1d6 */
export const hitChance = (target: number): number => (7 - target) / 6

export function rollToHit(dice: Dice, target: number): { roll: number, hit: boolean } {
  const roll = dice.d6()
  return { roll, hit: roll >= target }
}

/** Chance that a shot at an enemy engaged with an ally hits the ally */
export const friendlyFireChance = (): number => 1 / 6

/**
 * Draws one of `count` choices with d6s, each as likely as the others: a die above the last whole
 * multiple of `count` is rolled again (4 choices: 5 and 6 roll again). One choice rolls nothing
 */
export function drawWithDice(dice: Dice, count: number): number {
  if (count <= 1) return 0
  const limit = count * Math.floor(6 / count)
  for (;;) {
    const roll = dice.d6()
    if (roll <= limit) return (roll - 1) % count
  }
}
