import type * as ex from 'excalibur'
import type { Axial, HexLayout } from '../hex'
import type { MapData } from '../rules/terrain'
import { Resources } from '../resources'
import { ART_SIZE, GRID_LAYOUT, MAP1, MAP2, MAP3, hexAt, hexPixel } from './boards'

export type MapId = 'map1' | 'map2' | 'map3'

/**
 * A playable map: the terrain of the rules, the art it is drawn over and how
 * hexes and art pixels convert. The map list of the menu and the match read it
 * from here, so a new map is one more entry (and its texts in `t().onagro.maps`).
 */
export interface MapEntry {
  id: MapId
  data: MapData
  art: ex.ImageSource
  /** Size of the art, in pixels */
  size: { width: number, height: number }
  layout: HexLayout
  /** Center of a hex, in art pixels */
  hexPixel: (hex: Axial) => { x: number, y: number }
  /** The hex under an art pixel (null outside the map) */
  hexAt: (x: number, y: number) => Axial | null
}

/** Every map uses the same grid (boards.ts); only the terrain and the art change */
const entry = (id: MapId, data: MapData, art: ex.ImageSource): MapEntry =>
  ({ id, data, art, size: ART_SIZE, layout: GRID_LAYOUT, hexPixel, hexAt: (x, y) => hexAt(data, x, y) })

export const MAPS: MapEntry[] = [
  entry('map1', MAP1, Resources.Map1Art),
  entry('map2', MAP2, Resources.Map2Art),
  entry('map3', MAP3, Resources.Map3Art)
]

export const mapById = (id: string): MapEntry => MAPS.find(map => map.id === id) ?? MAPS[0]
