import { css, unsafeCSS } from 'lit'
import WoodPath from '../assets/ui/wood.png'
import WoodDarkPath from '../assets/ui/wood-dark.png'
import ParchmentPath from '../assets/ui/parchment.png'
import FramePlankPath from '../assets/ui/frame-plank.png'
import FrameGoldPath from '../assets/ui/frame-gold.png'
import FrameGoldSmallPath from '../assets/ui/frame-gold-small.png'
import FrameCartouchePath from '../assets/ui/frame-cartouche.png'
import FrameIronPath from '../assets/ui/frame-iron.png'
import FrameParchmentPath from '../assets/ui/frame-parchment.png'
import FrameBloodPath from '../assets/ui/frame-blood.png'
import FrameUndeadPath from '../assets/ui/frame-undead.png'
import BtnPath from '../assets/ui/btn.png'
import BtnHoverPath from '../assets/ui/btn-hover.png'
import BtnDownPath from '../assets/ui/btn-down.png'
import BtnOffPath from '../assets/ui/btn-off.png'
import BtnGoldPath from '../assets/ui/btn-gold.png'
import BtnGoldHoverPath from '../assets/ui/btn-gold-hover.png'
import BtnGoldDownPath from '../assets/ui/btn-gold-down.png'
import BtnRedPath from '../assets/ui/btn-red.png'
import GemPath from '../assets/ui/gem.png'
import BannerBluePath from '../assets/ui/banner-blue.png'
import BannerRedPath from '../assets/ui/banner-red.png'
import RivetPath from '../assets/ui/rivet.png'
import DiePath from '../assets/ui/die.png'
import DieDefPath from '../assets/ui/die-def.png'

const url = (path: string) => unsafeCSS(`url("${path}")`)

/** The pieces of `yarn ui` as CSS `url(...)`, for components that draw their own frames (the HUD) */
export const art = {
  wood: url(WoodPath),
  woodDark: url(WoodDarkPath),
  parchment: url(ParchmentPath),
  plank: url(FramePlankPath),
  gold: url(FrameGoldPath),
  goldSmall: url(FrameGoldSmallPath),
  cartouche: url(FrameCartouchePath),
  iron: url(FrameIronPath),
  parchmentFrame: url(FrameParchmentPath),
  blood: url(FrameBloodPath),
  btn: url(BtnPath),
  btnHover: url(BtnHoverPath),
  btnDown: url(BtnDownPath),
  btnOff: url(BtnOffPath),
  btnGold: url(BtnGoldPath),
  btnGoldHover: url(BtnGoldHoverPath),
  btnRed: url(BtnRedPath),
  gem: url(GemPath),
  bannerBlue: url(BannerBluePath),
  bannerRed: url(BannerRedPath),
  die: url(DiePath),
  dieDef: url(DieDefPath)
}

/**
 * Shared look of the menus and the HUD, in the identity of the Voxelhouse logo and cover:
 * dark wooden planks framed in light wood with iron brackets, golden frames with rivets and red
 * gems, parchment for long text. Every piece is pixel art from `yarn ui` (src/assets/ui/),
 * shown enlarged with `image-rendering: pixelated`.
 *
 * Sizes are written in "world pixels" with `--u`, so the UI scales with the canvas: `--s`
 * (page px per world px) is set by each overlay on its root. `--px` is the size of one pixel
 * of the art (3 world px in the menus; the HUD uses smaller ones).
 *
 * Pieces: `.panel` (planks), `.panel.gold` / `.frame-gold` (golden frame), `.cartouche`
 * (the "Mundo de Artrúsia" sign: golden bevel on black), `.parchment` (dark ink on paper),
 * `.frame-iron` (portraits), `.frame-blood` (danger), `.frame-undead` (the Berdolock card),
 * `.btn-solid` (wooden button; `.primary` gold rim, `.on` chosen, `.danger` red rim),
 * `.gold-text` (the letters of the logo), `.gem`, `.die`.
 */
export const theme = css`
  :host {
    /*
     * --u: layout unit = 1 world px at 1920x1080, times --ui-scale.
     * --t: text unit = --u times --text-scale. Use it for every font-size.
     * GameUI and the start screen set --s, --ui-scale and --text-scale.
     */
    --u: calc(var(--s, 1) * var(--ui-scale, 1) * 1px);
    --t: calc(var(--u) * var(--text-scale, 1));
    --px: calc(3 * var(--u));

    /* text: cream on wood */
    --ink: #f3e6c8;
    --muted: #b49a78;
    --dim: #6e5a44;
    /* wood, gold and iron of the logo */
    --wood-d: #2b170b;
    --wood: #3e2413;
    --wood-m: #4f2e18;
    --wood-l: #6b3f20;
    --wood-hl: #8a5530;
    --seam: #1c0f07;
    --outline: #140a04;
    --gold-d: #7a3e06;
    --gold-s: #b8650c;
    --gold: #f8c23a;
    --gold-hh: #ffe58a;
    --iron: #5d636c;
    --iron-l: #9aa1aa;
    --gem: #c01822;
    /* sides: heraldic blue and red, bright enough on wood */
    --blue: #5a8cff;
    --blue-dark: #1a3480;
    --red: #ff5a4e;
    --red-dark: #6a0e14;
    --hp: #6ad35a;
    --hp-mid: #f8c23a;
    --hp-low: #ff5a4e;
    --mp: #7fd0ff;
    --orange: #ff9a3c;
    /* older names, kept for the components */
    --panel: var(--wood);
    --panel-solid: var(--wood-d);
    --edge: var(--wood-hl);
    --shadow: #000;
    /* neutral accent for panels that don't belong to a team */
    --team: var(--gold);
    --team-dark: var(--gold-d);

    font-family: 'notjamslab14', monospace;
    color: var(--ink);
    -webkit-font-smoothing: none;
    image-rendering: pixelated;
    user-select: none;
  }

  /* keyboard hints are noise on touch screens */
  @media (hover: none) and (pointer: coarse) {
    .keys-only { display: none !important; }
  }

  .team-blue { --team: var(--blue); --team-dark: var(--blue-dark); }
  .team-red { --team: var(--red); --team-dark: var(--red-dark); }

  /* ------------------------------------------------------------ surfaces */

  /* the sign of the logo: dark planks in a light wooden frame with iron brackets */
  .panel {
    background: ${url(WoodPath)} 0 0 / calc(64 * var(--px)) calc(96 * var(--px)) var(--wood);
    background-clip: padding-box;
    border: calc(6 * var(--px)) solid transparent;
    border-image: ${url(FramePlankPath)} 6 / calc(6 * var(--px)) stretch;
    box-shadow: calc(2 * var(--px)) calc(2 * var(--px)) 0 rgba(0, 0, 0, 0.7);
  }
  .wood-dark { background: ${url(WoodDarkPath)} 0 0 / calc(64 * var(--px)) calc(96 * var(--px)) var(--wood-d); }

  /* the golden frame of the cover (rivets in the corners): what is chosen or important */
  .panel.gold, .frame-gold {
    border: calc(7 * var(--px)) solid transparent;
    border-image: ${url(FrameGoldPath)} 7 / calc(7 * var(--px)) stretch;
  }
  .frame-gold-small {
    border: calc(3 * var(--px)) solid transparent;
    border-image: ${url(FrameGoldSmallPath)} 3 / calc(3 * var(--px)) stretch;
  }
  .frame-iron {
    border: calc(3 * var(--px)) solid transparent;
    border-image: ${url(FrameIronPath)} 3 / calc(3 * var(--px)) stretch;
  }
  .frame-blood {
    background: ${url(WoodDarkPath)} 0 0 / calc(64 * var(--px)) calc(96 * var(--px)) var(--wood-d);
    background-clip: padding-box;
    border: calc(6 * var(--px)) solid transparent;
    border-image: ${url(FrameBloodPath)} 6 / calc(6 * var(--px)) stretch;
  }
  /* the Berdolock card: rose filigree on night blue */
  .frame-undead {
    background: #161c38;
    background-clip: padding-box;
    border: calc(7 * var(--px)) solid transparent;
    border-image: ${url(FrameUndeadPath)} 7 / calc(7 * var(--px)) stretch;
  }
  /* the "Mundo de Artrúsia" sign: golden bevel on black, cut corners */
  .cartouche {
    background: none;
    border: calc(8 * var(--px)) solid transparent;
    border-image: ${url(FrameCartouchePath)} 8 fill / calc(8 * var(--px)) stretch;
  }
  /* paper for long text: the colors turn to dark ink */
  .parchment {
    --ink: #2e1c0e;
    --muted: #6b4f32;
    --dim: #a08060;
    --gold: #8a4a08;
    --gold-hh: #b8650c;
    --blue: #1d47a8;
    --red: #a01a1a;
    --hp: #2f7a22;
    --hp-low: #a01a1a;
    --orange: #a84a00;
    --mp: #1a5a8a;
    color: var(--ink);
    background: ${url(ParchmentPath)} 0 0 / calc(16 * var(--px)) #e8d3a2;
    background-clip: padding-box;
    border: calc(4 * var(--px)) solid transparent;
    border-image: ${url(FrameParchmentPath)} 4 / calc(4 * var(--px)) stretch;
  }

  /* title strip of a panel: golden letters over a darker band */
  .panel-title {
    display: flex;
    align-items: center;
    gap: calc(8 * var(--u));
    padding: calc(8 * var(--u)) calc(12 * var(--u));
    background: rgba(20, 10, 4, 0.55);
    color: var(--gold);
    text-shadow: var(--px) var(--px) 0 var(--outline);
    border-bottom: var(--px) solid var(--seam);
    box-shadow: 0 var(--px) 0 var(--wood-hl);
    font-size: calc(22 * var(--t));
    line-height: 1;
  }

  /* the letters of the logo: banded gold, dark outline, deep shadow */
  .gold-text {
    color: var(--gold);
    background: linear-gradient(180deg, var(--gold-hh) 0 30%, var(--gold) 30% 62%, #e8961a 62% 82%, var(--gold-s) 82%);
    background-size: 100% 1lh;
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    filter:
      drop-shadow(calc(1 * var(--px) / 1.5) 0 0 var(--outline))
      drop-shadow(calc(-1 * var(--px) / 1.5) 0 0 var(--outline))
      drop-shadow(0 calc(1 * var(--px) / 1.5) 0 var(--outline))
      drop-shadow(0 calc(-1 * var(--px) / 1.5) 0 var(--outline))
      drop-shadow(0 var(--px) 0 var(--gold-d))
      drop-shadow(var(--px) var(--px) 0 rgba(0, 0, 0, 0.85));
  }
  /* small caps line under a title, like the logo's tagline */
  .tagline { color: var(--gold); text-transform: uppercase; letter-spacing: 0.12em; text-shadow: calc(var(--px) / 1.5) calc(var(--px) / 1.5) 0 var(--outline); }

  .muted { color: var(--muted); }

  /* pieces to decorate */
  .gem { display: inline-block; width: calc(9 * var(--px)); height: calc(11 * var(--px)); background: ${url(GemPath)} center / 100% 100% no-repeat; flex: none; }
  .rivet { display: inline-block; width: calc(5 * var(--px)); height: calc(5 * var(--px)); background: ${url(RivetPath)} center / 100% 100% no-repeat; flex: none; }

  /* a die: bone for the attack, steel for the defense */
  .die {
    box-sizing: border-box;
    border: calc(3 * var(--dpx, var(--px))) solid transparent;
    border-image: ${url(DiePath)} 3 fill / calc(3 * var(--dpx, var(--px))) stretch;
    color: #1a0f06;
  }
  .die.def { border-image-source: ${url(DieDefPath)}; }

  /* Segmented pixel bar: <div class="bar hp"><i style="width: 60%"></i></div> */
  .bar {
    position: relative;
    height: calc(12 * var(--u));
    background: #000;
    border: calc(2 * var(--u)) solid #000;
    box-shadow: 0 0 0 calc(2 * var(--u)) var(--iron);
    overflow: hidden;
  }
  .bar > i {
    position: absolute;
    inset: 0 auto 0 0;
    background: var(--fill, var(--hp));
    transition: width 250ms steps(6);
  }
  .bar > i.ghost {
    background: #fff;
    animation: ghost 700ms steps(2) infinite;
  }
  .bar::after {
    content: '';
    position: absolute;
    inset: 0;
    background: repeating-linear-gradient(90deg, transparent 0 calc(7 * var(--u)), rgba(0, 0, 0, 0.55) calc(7 * var(--u)) calc(9 * var(--u)));
    pointer-events: none;
  }
  .bar.hp { --fill: var(--hp); }
  .bar.hp.mid { --fill: var(--hp-mid); }
  .bar.hp.low { --fill: var(--hp-low); }
  .bar.mp { --fill: var(--mp); }

  @keyframes ghost {
    50% { opacity: 0.25; }
  }

  /* ------------------------------------------------------------ buttons */

  /* a plain button (lists, links): gold on hover */
  .btn {
    all: unset;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    gap: calc(8 * var(--u));
    padding: calc(7 * var(--u)) calc(12 * var(--u));
    font-size: calc(20 * var(--t));
    line-height: 1;
    color: var(--ink);
    cursor: pointer;
    background: transparent;
  }
  .btn:hover:not(:disabled),
  .btn:focus-visible:not(:disabled) {
    background: rgba(248, 194, 58, 0.14);
    color: var(--gold-hh);
  }
  .btn:active:not(:disabled) {
    filter: brightness(1.25);
  }
  .btn:disabled {
    color: var(--dim);
    cursor: default;
  }

  /* a wooden plank button; the gold rim marks the main action and the chosen option */
  .btn-solid {
    justify-content: center;
    background: none;
    color: var(--ink);
    border: calc(4 * var(--px)) solid transparent;
    border-image: ${url(BtnPath)} 4 fill / calc(4 * var(--px)) stretch;
    padding: calc(4 * var(--u)) calc(10 * var(--u));
    text-shadow: calc(var(--px) / 1.5) calc(var(--px) / 1.5) 0 var(--outline);
    filter: drop-shadow(var(--px) var(--px) 0 rgba(0, 0, 0, 0.7));
  }
  .btn-solid:hover:not(:disabled),
  .btn-solid:focus-visible:not(:disabled) {
    background: none;
    border-image-source: ${url(BtnHoverPath)};
    color: var(--gold-hh);
    text-shadow: calc(var(--px) / 1.5) calc(var(--px) / 1.5) 0 var(--outline);
  }
  .btn-solid:active:not(:disabled) {
    border-image-source: ${url(BtnDownPath)};
    transform: translate(calc(var(--px) / 1.5), calc(var(--px) / 1.5));
    filter: none;
  }
  .btn-solid:disabled {
    border-image-source: ${url(BtnOffPath)};
    color: #8a8076;
    filter: none;
  }
  .btn-solid.primary, .btn-solid.on {
    border-image-source: ${url(BtnGoldPath)};
    color: var(--gold);
  }
  .btn-solid.primary:hover:not(:disabled), .btn-solid.primary:focus-visible:not(:disabled),
  .btn-solid.on:hover:not(:disabled), .btn-solid.on:focus-visible:not(:disabled) {
    border-image-source: ${url(BtnGoldHoverPath)};
    color: var(--gold-hh);
  }
  .btn-solid.primary:active:not(:disabled), .btn-solid.on:active:not(:disabled) {
    border-image-source: ${url(BtnGoldDownPath)};
  }
  .btn-solid.on:disabled { border-image-source: ${url(BtnGoldPath)}; color: var(--gold); }
  .btn-solid.danger { border-image-source: ${url(BtnRedPath)}; }
  /* keyboard and gamepad focus: a blinking golden outline */
  .btn-solid:focus-visible { outline: calc(var(--px) / 1.5) solid var(--gold-hh); outline-offset: calc(var(--px) / 1.5); animation: focus-blink 900ms steps(2) infinite; }
  @keyframes focus-blink { 50% { outline-color: transparent; } }

  /* small iron-rimmed plate with a label */
  .chip {
    display: inline-block;
    padding: calc(3 * var(--u)) calc(8 * var(--u));
    font-size: calc(14 * var(--t));
    line-height: 1.2;
    background: rgba(20, 10, 4, 0.5);
    border: calc(2 * var(--px)) solid transparent;
    border-image: ${url(FrameIronPath)} 3 / calc(2 * var(--px)) stretch;
  }
`
