import * as ex from 'excalibur'

/**
 * Browsers keep a page silent until the person clicks, taps or presses a key on it (a click made
 * by code does not count). There is no PLAY! button to get that first gesture: the title music
 * starts right away when the browser allows it (Chrome does on sites the person often listens to),
 * else the first gesture anywhere on the page turns the sound on, and the music, already started on
 * the silent context, is heard from then on. The title screen shows a button while it is silent.
 */

const GESTURES = ['pointerdown', 'pointerup', 'click', 'touchend', 'keydown'] as const
const listeners = new Set<() => void>()

function context(): AudioContext | null {
  return ex.AudioContextFactory.create() ?? null
}

/** The browser still keeps the sound off (no gesture yet) */
export function soundBlocked(): boolean {
  const audio = context()
  return !!audio && audio.state !== 'running'
}

/** Called once when the sound comes on; returns the unsubscribe function */
export function onSoundUnblocked(listener: () => void): () => void {
  listeners.add(listener)
  return () => listeners.delete(listener)
}

/** Turns the sound on: only works inside the handler of a click, tap or key press */
export function unlockSound() {
  void ex.WebAudio.unlock()
}

/** From the first click, tap or key anywhere on the page, the sound is on (call once, at start) */
export function unlockSoundOnFirstGesture() {
  const audio = context()
  if (!audio) return
  const gesture = () => unlockSound()
  const done = () => {
    if (audio.state !== 'running') return
    for (const type of GESTURES) window.removeEventListener(type, gesture, true)
    audio.removeEventListener('statechange', done)
    for (const listener of [...listeners]) listener()
    listeners.clear()
  }
  for (const type of GESTURES) window.addEventListener(type, gesture, true)
  audio.addEventListener('statechange', done)
  done()
}
