import { LitElement, css, html, nothing, unsafeCSS } from 'lit'
import { customElement, property, state } from 'lit/decorators.js'
import { theme } from './theme'
import FrameGoldPath from '../assets/ui/frame-gold.png'
import FrameGoldSmallPath from '../assets/ui/frame-gold-small.png'
import FrameIronPath from '../assets/ui/frame-iron.png'
import { t } from '../i18n'
import { MAPS, MapEntry, MapId } from '../onagro/maps'
import { DEFAULT_MAX_TURNS } from '../rules/game'

/**
 * Map selector: the list of maps on the left, the highlighted one large on the right
 * with its description. Keyboard: ↑/↓ choose, Enter next, Esc back.
 * Fires `start` (detail = map id), `select` and `back`.
 */
@customElement('map-select')
export class MapSelect extends LitElement {
  static styles = [theme, css`
    :host { display: block; width: calc(1840 * var(--u)); max-width: 96vw; }
    .header { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: calc(14 * var(--u)); }
    h2 { margin: 0; font-weight: normal; font-size: calc(44 * var(--t)); }
    .title { display: flex; align-items: center; gap: calc(16 * var(--u)); }
    .mode { font-size: calc(18 * var(--t)); color: var(--muted); }
    .mode b { font-weight: normal; color: var(--gold); }

    .layout { display: grid; grid-template-columns: calc(380 * var(--u)) 1fr; gap: calc(24 * var(--u)); }

    .list { display: flex; flex-direction: column; min-height: 0; }
    .list .panel-title { font-size: calc(18 * var(--t)); justify-content: space-between; }
    .items { flex: 1; overflow-y: auto; padding: calc(8 * var(--u)); display: flex; flex-direction: column; gap: calc(8 * var(--u)); scrollbar-color: var(--edge) transparent; }
    .item {
      all: unset;
      box-sizing: border-box;
      display: grid;
      grid-template-columns: calc(128 * var(--u)) 1fr;
      gap: calc(12 * var(--u));
      align-items: center;
      padding: calc(6 * var(--u));
      background: rgba(20, 10, 4, 0.35);
      border: calc(3 * var(--px)) solid transparent;
      border-image: url(${unsafeCSS(FrameIronPath)}) 3 / calc(3 * var(--px)) stretch;
      cursor: pointer;
    }
    .item:hover { background: rgba(248, 194, 58, 0.1); }
    .item.selected { border-image-source: url(${unsafeCSS(FrameGoldSmallPath)}); background: rgba(248, 194, 58, 0.14); }
    .item.selected .name { color: var(--gold-hh); }
    .thumb { width: 100%; object-fit: cover; box-sizing: border-box; background: #000; }
    .item .name { font-size: calc(20 * var(--t)); line-height: 1.1; }
    .item .meta { font-size: calc(14 * var(--t)); color: var(--muted); margin-top: calc(4 * var(--u)); }

    /* every map at the same size, in the art's own proportions (no bars), and the texts in a column beside it */
    .detail { display: grid; grid-template-columns: calc(920 * var(--u)) 1fr; min-height: 0; }
    .preview { position: relative; align-self: start; background: #000; overflow: hidden; }
    .preview::after { content: ''; position: absolute; inset: 0; border: calc(7 * var(--px)) solid transparent; border-image: url(${unsafeCSS(FrameGoldPath)}) 7 / calc(7 * var(--px)) stretch; pointer-events: none; }
    .preview > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; display: block; }

    .side { display: flex; flex-direction: column; min-width: 0; min-height: 0; }
    .info { flex: 1; min-height: 0; display: flex; flex-direction: column; gap: calc(12 * var(--u)); padding: calc(18 * var(--u)) calc(20 * var(--u)) calc(10 * var(--u)); }
    .info h3 { margin: 0; font-weight: normal; font-size: calc(32 * var(--t)); line-height: 1.1; }
    /* a long description scrolls inside its column: the map never changes size */
    .info p {
      margin: 0; flex: 1 1 0; min-height: 0; overflow-y: auto; padding-right: calc(6 * var(--u));
      font-size: calc(17 * var(--t)); line-height: 1.35; color: var(--muted); scrollbar-color: var(--edge) transparent;
    }
    .chips { display: flex; flex-wrap: wrap; gap: calc(8 * var(--u)); }
    .chips .chip { color: var(--ink); font-size: calc(15 * var(--t)); }

    .actions { display: flex; flex-wrap: wrap; gap: calc(12 * var(--u)); padding: 0 calc(20 * var(--u)) calc(18 * var(--u)); }
    .actions .btn { font-size: calc(24 * var(--t)); padding: calc(10 * var(--u)) calc(22 * var(--u)); }
    .actions .start { flex: 1; }
    .keys { flex-basis: 100%; font-size: calc(14 * var(--t)); color: var(--muted); }
  `]

  /** Label of the chosen mode, shown in the header */
  @property()
    modeLabel = ''

  /** Map highlighted when the screen opens */
  @property()
    initial: MapId = MAPS[0].id

  @state()
  private selected: MapId | null = null

  private onKeyDown = (event: KeyboardEvent) => {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const index = MAPS.findIndex(map => map.id === this.current().id)
      const next = (index + (event.key === 'ArrowDown' ? 1 : -1) + MAPS.length) % MAPS.length
      this.select(MAPS[next].id)
    } else if (event.key === 'Enter') {
      event.preventDefault()
      this.start()
    } else if (event.key === 'Escape') {
      this.dispatchEvent(new Event('back'))
    }
  }

  override connectedCallback() {
    super.connectedCallback()
    window.addEventListener('keydown', this.onKeyDown)
  }

  override disconnectedCallback() {
    window.removeEventListener('keydown', this.onKeyDown)
    super.disconnectedCallback()
  }

  private current(): MapEntry {
    const id = this.selected ?? this.initial
    return MAPS.find(map => map.id === id) ?? MAPS[0]
  }

  private select(id: MapId) {
    this.selected = id
    this.dispatchEvent(new CustomEvent<MapId>('select', { detail: id }))
    void this.updateComplete.then(() => this.shadowRoot?.querySelector('.item.selected')?.scrollIntoView({ block: 'nearest' }))
  }

  private start() {
    this.dispatchEvent(new CustomEvent<MapId>('start', { detail: this.current().id }))
  }

  private renderItem(map: MapEntry, selected: boolean) {
    const text = t().onagro.maps
    return html`
      <button class="item ${selected ? 'selected' : ''}" @click=${() => this.select(map.id)} @dblclick=${() => this.start()}>
        <img class="thumb" src=${map.art.path} alt="" style="aspect-ratio: ${map.size.width} / ${map.size.height}" />
        <div>
          <div class="name">${text[map.id].name}</div>
          <div class="meta">${text.hexes(map.data.cols, map.data.rows)}</div>
        </div>
      </button>
    `
  }

  override render() {
    const text = t().onagro.maps
    const map = this.current()
    return html`
      <div class="header">
        <div class="title"><i class="gem"></i><h2 class="gold-text">${text.heading}</h2></div>
        ${this.modeLabel ? html`<div class="mode">${text.mode} <b>${this.modeLabel}</b></div>` : nothing}
      </div>
      <div class="layout">
        <div class="panel list">
          <div class="panel-title"><span>${text.list}</span><span>${MAPS.length}</span></div>
          <div class="items">${MAPS.map(m => this.renderItem(m, m.id === map.id))}</div>
        </div>
        <div class="panel detail">
          <div class="preview" style="aspect-ratio: ${map.size.width} / ${map.size.height}"><img src=${map.art.path} alt=${text[map.id].name} /></div>
          <div class="side">
            <div class="info">
              <h3 class="gold-text">${text[map.id].name}</h3>
              <p>${text[map.id].description}</p>
              <div class="chips">
                <span class="chip">${text.hexes(map.data.cols, map.data.rows)}</span>
                <span class="chip">${text.turns(DEFAULT_MAX_TURNS)}</span>
                <span class="chip">${text.zones}</span>
              </div>
            </div>
            <div class="actions">
              <span class="keys"><span class="keys-only">${text.keys}</span></span>
              <button class="btn btn-solid back" @click=${() => this.dispatchEvent(new Event('back'))}>${t().common.back}</button>
              <button class="btn btn-solid primary start" @click=${() => this.start()}>${text.next}</button>
            </div>
          </div>
        </div>
      </div>
    `
  }
}
